import json, re
schema = json.load(open("agents/response.schema.json"))
doc = json.load(open("review.json"))
ctx = json.load(open("context.json"))
errs = []

# Minimal draft-2020-12 validator for the keywords this schema uses
def v(node, sch, path):
    t = sch.get("type")
    tmap = {"object": dict, "array": list, "string": str, "integer": int}
    if "const" in sch and node != sch["const"]:
        errs.append(f"{path}: const {sch[\"const\"]!r} != {node!r}")
    if t:
        ok = isinstance(node, tmap[t]) and not (t == "integer" and isinstance(node, bool))
        if not ok:
            errs.append(f"{path}: expected {t}, got {type(node).__name__}"); return
    if "enum" in sch and node not in sch["enum"]:
        errs.append(f"{path}: {node!r} not in enum {sch[\"enum\"]}")
    if "pattern" in sch and not re.search(sch["pattern"], node):
        errs.append(f"{path}: pattern {sch[\"pattern\"]} failed")
    if t == "object":
        props = sch.get("properties", {})
        for r in sch.get("required", []):
            if r not in node: errs.append(f"{path}: missing required {r}")
        if sch.get("additionalProperties") is False:
            for k in node:
                if k not in props: errs.append(f"{path}: additional property {k}")
        for k, s in props.items():
            if k in node: v(node[k], s, f"{path}.{k}")
    if t == "array" and "items" in sch:
        for i, it in enumerate(node): v(it, sch["items"], f"{path}[{i}]")

v(doc, schema, "$")
print("schema errors:", errs if errs else "none")

# Hash equality with context.json
for k in ("schemaVersion", "snapshotHash", "contextHash"):
    print(k, "match" if doc[k] == ctx[k] else f"MISMATCH {doc[k]} vs {ctx[k]}")

# Span checks
files = {f["path"]: f for f in ctx["files"]}
for i, o in enumerate(doc["review"]["observations"]):
    for s in o["source"]:
        f = files.get(s["path"])
        if f is None: print("UNKNOWN PATH", s); continue
        ok = 1 <= s["start"] <= s["end"] <= f["lines"]
        last = f["content"].split("\n")[s["end"]-1]
        print(f"obs{i+1} {s[\"path\"].split(\"/\")[-1]}:{s[\"start\"]}-{s[\"end\"]} in-range={ok} nonblank-end={bool(last.strip())}")
print("observations:", len(doc["review"]["observations"]), "gaps:", len(doc["review"]["gaps"]))
'

